<?php
declare(strict_types=1); require_once __DIR__.'/_guard.php'; dash_require('events'); dash_require_hq(); require_once __DIR__.'/../event-lib.php';
$pdo=dash_pdo();$events=$pdo->query('SELECT id,title FROM events ORDER BY event_date DESC')->fetchAll();$eventId=(int)($_GET['event_id']??0);$sql="SELECT n.*,e.title event_title FROM event_news n JOIN events e ON e.id=n.event_id";if($eventId)$sql.=' WHERE n.event_id='.($eventId);$sql.=' ORDER BY n.updated_at DESC';$news=$pdo->query($sql)->fetchAll();$PANEL_TITLE='اخبار رویدادها';require __DIR__.'/_panel_head.php';
?><style>.news-toolbar{display:flex;align-items:end;justify-content:space-between;gap:14px;flex-wrap:wrap;margin-bottom:20px}.news-toolbar select{height:42px;border:1px solid var(--color-border);border-radius:10px;background:var(--color-surface);font:inherit;padding:0 12px;color:var(--color-text)}.news-table{width:100%;overflow:auto}.news-table table{min-width:680px}</style><div class="news-toolbar"><div><h1>اخبار رویدادها</h1><p class="sub">خبرهایی که فقط در صفحه یک رویداد نمایش داده می‌شوند</p></div><div class="actions"><form method="get"><select name="event_id" onchange="this.form.submit()"><option value="0">همه رویدادها</option><?php foreach($events as $e): ?><option value="<?= (int)$e['id'] ?>" <?= $eventId===$e['id']?'selected':'' ?>><?= event_h($e['title']) ?></option><?php endforeach; ?></select></form><?php if($eventId): ?><a class="btn btn-primary" href="event-news-create.php?event_id=<?= $eventId ?>">＋ خبر جدید</a><?php endif; ?></div></div><div class="card news-table"><table class="tbl"><thead><tr><th>عنوان</th><th>رویداد</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($news as $n): ?><tr><td data-label="عنوان"><?= event_h($n['title']) ?></td><td data-label="رویداد"><?= event_h($n['event_title']) ?></td><td data-label="وضعیت"><span class="badge <?= $n['status']==='published'?'ok':'off' ?>"><?= $n['status']==='published'?'منتشرشده':'پیش‌نویس' ?></span></td><td data-label="عملیات"><a class="tbtn" href="event-news-create.php?id=<?= (int)$n['id'] ?>">ویرایش</a></td></tr><?php endforeach; if(!$news): ?><tr><td colspan="4" class="empty-state">هنوز خبری برای رویدادها ثبت نشده است.</td></tr><?php endif; ?></tbody></table></div></div></body></html>
